import{Ct as e,ct as t,lt as n,q as r}from"./chunks/framework.BVmwMUcr.js";var i=JSON.parse(`{"title":"Deferred Exam Application Guide","description":"Conditions, documentation, approval, receipt, and retake confirmation process for SCUT undergraduates applying for a deferred exam due to illness or schedule conflict","frontmatter":{"lang":"en-US","title":"Deferred Exam Application Guide","description":"Conditions, documentation, approval, receipt, and retake confirmation process for SCUT undergraduates applying for a deferred exam due to illness or schedule conflict","llm_translated":true},"headers":[],"relativePath":"en/learn/curricular/deferred_exam.md","filePath":"en/learn/curricular/deferred_exam.md","lastUpdated":1785216348000}`),a={name:`en/learn/curricular/deferred_exam.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /en/learn/curricular/deferred_exam.md for this page in Markdown format</div><h1 id="deferred-exam-application-guide-don-t-gamble-your-exam-on-luck" tabindex="-1">Deferred Exam Application Guide: Don&#39;t Gamble Your Exam on Luck <a class="header-anchor" href="#deferred-exam-application-guide-don-t-gamble-your-exam-on-luck" aria-label="Permalink to “Deferred Exam Application Guide: Don&#39;t Gamble Your Exam on Luck”">​</a></h1><p>A deferred exam is <strong>not</strong> &quot;I&#39;ll just skip it and take it next semester&quot; — it requires <strong>a written application submitted and approved before the exam</strong>. Missing an exam without completing this process is considered an unauthorized absence, not a deferral. SCUT&#39;s current academic regulations allow deferred exams in two situations:</p><ul><li>Illness preventing attendance, supported by a hospital certificate;</li><li>Schedule conflicts preventing attendance.</li></ul><p>The applicant must submit a written application to both their home college and the course-offering college before the exam, approved by the vice deans of both colleges, in order to take the retake at the beginning of the next semester. Although deferred exam students sit the same exam as retake students, the grade is <strong>not recorded as a retake grade</strong>.</p><div class="info custom-block"><p class="custom-block-title">Scope of verification</p><p>The offline procedure described below is based on two deferred exam applications processed by a student from the School of Civil and Transportation during the 2025–2026 academic year: one due to high fever, and another due to a schedule conflict between UC Berkeley&#39;s summer session and SCUT&#39;s exam. In both cases, the home college and course-offering college were the same (School of Civil and Transportation).</p><p>Cross-college applications and last-minute illness on exam day have not been personally tested. If you encounter either situation, check with your counselor first — don&#39;t bet your academic record on this page.</p></div><h2 id="one-page-checklist" tabindex="-1">One-Page Checklist <a class="header-anchor" href="#one-page-checklist" aria-label="Permalink to “One-Page Checklist”">​</a></h2><ol><li>Ask your counselor for the current semester&#39;s application form, and confirm the teaching secretary and stamping office locations.</li><li>Notify your course instructor via WeChat that you plan to apply for a deferred exam, so you won&#39;t be marked as absent without excuse.</li><li>Prepare evidence that covers the exam period.</li><li>Fill out one form per course.</li><li>Have the teaching secretary process the approval comments for both your home college and the course-offering college.</li><li>Complete the vice dean&#39;s signature stamp, two college official stamps on the approval blocks, and the receipt stamp.</li><li>Photograph the completed form, submit it to the course-offering college for filing as required, and give the stamped receipt to your instructor before the exam.</li><li>After the next semester begins, complete &quot;retake enrollment confirmation&quot; in the academic system, then check the exam schedule.</li></ol><h2 id="step-1-ask-your-counselor-first-—-don-t-download-forms-from-the-web" tabindex="-1">Step 1: Ask Your Counselor First — Don&#39;t Download Forms from the Web <a class="header-anchor" href="#step-1-ask-your-counselor-first-—-don-t-download-forms-from-the-web" aria-label="Permalink to “Step 1: Ask Your Counselor First — Don&#39;t Download Forms from the Web”">​</a></h2><p>The university website has a <a href="https://www2.scut.edu.cn/ep/2018/1102/c19008a293383/page.htm" target="_blank" rel="noreferrer">deferred exam application form download page</a>, but the public page was published in 2018 and the form&#39;s footer dates back even further. The safer approach is to ask your counselor directly:</p><blockquote><p>I need to apply for a deferred exam for [course name]. Could you tell me which version of the form is in use this semester? Which teaching secretaries handle the home college and course-offering college approvals, and which offices should I go to for stamps?</p></blockquote><p>Your counselor&#39;s value isn&#39;t to approve you — it&#39;s to give you the current form version and real office routes. The official form says &quot;approved by the vice dean of teaching,&quot; but in practice, the authorized teaching secretary may handle the signature stamp and college stamp.</p><h2 id="step-2-notify-your-instructor" tabindex="-1">Step 2: Notify Your Instructor <a class="header-anchor" href="#step-2-notify-your-instructor" aria-label="Permalink to “Step 2: Notify Your Instructor”">​</a></h2><p>The course instructor is not the final approver, but they must know in advance that you are not an unauthorized absentee. You can send:</p><blockquote><p>Professor [Name], I am [Your Name], student ID [Number], enrolled in your course [Course Name]. The original exam is scheduled for [Date] at [Time]. Due to [Reason], I cannot attend. I plan to apply for a deferred exam through my college&#39;s procedure and wanted to notify you first. Once the approval is complete, I will send you the stamped materials and deliver the paper receipt before the exam.</p></blockquote><p>In practice, verbal acknowledgment via WeChat from the instructor is sufficient to proceed. The &quot;instructor&quot; column on the form can be filled in by the student. The instructor&#39;s acknowledgment is a notification, not college approval.</p><h2 id="step-3-solidify-your-evidence" tabindex="-1">Step 3: Solidify Your Evidence <a class="header-anchor" href="#step-3-solidify-your-evidence" aria-label="Permalink to “Step 3: Solidify Your Evidence”">​</a></h2><h3 id="due-to-illness" tabindex="-1">Due to Illness <a class="header-anchor" href="#due-to-illness" aria-label="Permalink to “Due to Illness”">​</a></h3><p>The tested path is:</p><ol><li>Visit the university hospital and register for a consultation;</li><li>Ask the attending physician to issue a diagnosis based on your actual condition;</li><li>Obtain a clear medical recommendation, e.g., &quot;recommended rest for 1 day&quot;;</li><li>Present the diagnosis and recommendation when processing approval.</li></ol><p>In one actual application, the diagnosis recorded a peak body temperature of <code>39.5°C</code> and related symptoms, with a doctor&#39;s recommendation of 1 day of rest. The university hospital could issue at most 1–2 days of rest recommendation at the time. The college did not retain the materials, but the stamping officer needed to see them on-site.</p><p>What matters is not the word &quot;fever,&quot; but <strong>symptom records, diagnostic conclusions, and a rest recommendation covering the exam period</strong>. Doctors must write based on actual examination results — do not instruct them to fabricate wording.</p><p>The university&#39;s official rules only require a hospital certificate and do not publicly specify that it must be from the university hospital or mandate a fixed template. If using an external hospital, needing a longer rest period, or facing an emergency, confirm material requirements with your counselor first.</p><h3 id="due-to-schedule-conflict" tabindex="-1">Due to Schedule Conflict <a class="header-anchor" href="#due-to-schedule-conflict" aria-label="Permalink to “Due to Schedule Conflict”">​</a></h3><p>Do <strong>not</strong> interpret &quot;business&quot; as &quot;any plane ticket qualifies.&quot; The official rule states <strong>course conflict</strong>.</p><p>One actual approved case: UC Berkeley&#39;s summer session started on July 6, and SCUT&#39;s exam was on July 7. The applicant presented their I-20 and was approved, without being asked to provide a plane ticket or explain why the trip couldn&#39;t be rescheduled. This only proves that &quot;external course conflict + I-20&quot; was once approved — it does not imply that personal travel, tourism, or ordinary schedule conflicts will be approved.</p><p>If your situation is not a course conflict, send your evidence to your counselor first to ask whether it&#39;s worth applying. Do not buy non-refundable tickets first and then expect the college to bail you out.</p><h2 id="step-4-fill-out-the-application-form" tabindex="-1">Step 4: Fill Out the Application Form <a class="header-anchor" href="#step-4-fill-out-the-application-form" aria-label="Permalink to “Step 4: Fill Out the Application Form”">​</a></h2><p>Blank sections must be handwritten, one form per course. You cannot use one form for multiple courses. Required fields include:</p><ul><li>Name, student ID, home college, and major;</li><li>Course name and instructor;</li><li>Original exam time;</li><li>Whether you have read and understood the relevant regulations;</li><li>Reason for application;</li><li>Student signature and date.</li></ul><p>Verify the course name and exam time from the academic system or exam notice before filling in — don&#39;t rely on abbreviations. Supporting documents do not need to be glued to the form, but you must bring the originals or verifiable materials when processing.</p><h2 id="step-5-complete-the-approval-and-three-official-stamps" tabindex="-1">Step 5: Complete the Approval and Three Official Stamps <a class="header-anchor" href="#step-5-complete-the-approval-and-three-official-stamps" aria-label="Permalink to “Step 5: Complete the Approval and Three Official Stamps”">​</a></h2><p>In the tested case where the home college and course-offering college were the same, a single teaching secretary handled both &quot;Vice Dean&#39;s Opinion&quot; columns. The sequence was:</p><ol><li>Review the application reason and evidence;</li><li>Write the approval opinion;</li><li>Apply the vice dean&#39;s signature stamp;</li><li>Stamp both the &quot;Home College&quot; and &quot;Course-Offering College&quot; official seals;</li><li>Stamp the &quot;Deferred Exam Receipt&quot; with the course-offering college seal one more time.</li></ol><p>Even when both colleges are the same, the two columns cannot be combined — the form requires three college stamps in total. The signature stamp and college stamps may be handled in different offices. With complete materials and all relevant staff present, approval took about 10 minutes in practice. The real delay comes from finding the wrong office or the responsible person being away.</p><p>If the course-offering college is not your home college, follow the order of &quot;home college first, then course-offering college,&quot; and confirm the teaching secretaries for both colleges in advance. The cross-college route has not been personally tested — do not copy the School of Civil and Transportation&#39;s office arrangements.</p><h2 id="step-6-file-submit-the-receipt-and-keep-evidence" tabindex="-1">Step 6: File, Submit the Receipt, and Keep Evidence <a class="header-anchor" href="#step-6-file-submit-the-receipt-and-keep-evidence" aria-label="Permalink to “Step 6: File, Submit the Receipt, and Keep Evidence”">​</a></h2><p>The form&#39;s printed instructions require:</p><ul><li>After approval, submit to the course-offering college&#39;s academic affairs office before the exam;</li><li>The top portion is retained by the course-offering college for filing;</li><li>The bottom receipt, stamped by the course-offering college, is given to the course instructor.</li></ul><p>In practice, if the office returns the entire form to you, do not guess which section to cut. Ask on the spot: &quot;Which part does the college keep, and which part does the instructor receive?&quot; Before handing over any paper, take a clear photo showing the handwriting and all three stamps.</p><p>If you cannot submit in person, a classmate can do it for you, but at minimum:</p><ol><li>Send the complete stamped version to your instructor before the exam;</li><li>Tell the person clearly who to give it to and which part to submit;</li><li>Have the instructor or your classmate confirm delivery;</li><li>Save the chat records and the complete photo.</li></ol><p>When the instructor enters grades for this term, the course will be marked as &quot;deferred exam.&quot; The paper receipt&#39;s purpose is to ensure the instructor knows this is not an unauthorized absence.</p><h2 id="step-7-don-t-forget-to-enroll-next-semester" tabindex="-1">Step 7: Don&#39;t Forget to Enroll Next Semester <a class="header-anchor" href="#step-7-don-t-forget-to-enroll-next-semester" aria-label="Permalink to “Step 7: Don&#39;t Forget to Enroll Next Semester”">​</a></h2><p>Approval for a deferred exam only resolves &quot;why you didn&#39;t take it this time&quot; — it does not automatically enroll you for the next sitting.</p><p>At the start of the next semester, the college will notify students to log into the academic system. The menu path is:</p><blockquote><p>Applications → Retake Enrollment Confirmation</p></blockquote><p>For example, in the 2025–2026 academic year, second semester notification opened from Wednesday of the first week to Wednesday of the second week — a window of only one week. Specific dates change each semester; only the current semester&#39;s notice is authoritative.</p><p>After enrolling, check two sources for arrangements:</p><ul><li>Public courses: check the Undergraduate Academic Affairs Office or the course-offering college&#39;s retake schedule;</li><li>Major-specific courses: check the course-offering college&#39;s official website for undergraduate academic notices.</li></ul><p>Deferred exam students typically sit the same exam as makeup and retake students, but this is only a shared exam arrangement. An approved deferred exam grade is not recorded as a retake grade. The overall course assessment still follows the original evaluation method, and your usual performance score is not voided.</p><p>You only get one retake opportunity. If you miss the &quot;retake enrollment confirmation&quot; window, or enroll but fail to show up, the only remaining option is course retaking. Don&#39;t leave a one-week window to your memory — set a reminder on the first day of the semester.</p><h2 id="four-common-pitfalls" tabindex="-1">Four Common Pitfalls <a class="header-anchor" href="#four-common-pitfalls" aria-label="Permalink to “Four Common Pitfalls”">​</a></h2><ol><li><strong>&quot;The instructor agreed, so I&#39;m good.&quot;</strong> No. The instructor is just informed — final approval requires both colleges.</li><li><strong>&quot;One stamp from the same college is enough.&quot;</strong> No. The home college column, course-offering college column, and receipt each have their own stamp.</li><li><strong>&quot;Any reason works.&quot;</strong> Not true. The published rules cover illness or course conflict. Other reasons are at the college&#39;s discretion.</li><li><strong>&quot;Once approved, I just wait.&quot;</strong> No. You must actively confirm enrollment in the academic system next semester.</li></ol><h2 id="sources-and-timeliness" tabindex="-1">Sources and Timeliness <a class="header-anchor" href="#sources-and-timeliness" aria-label="Permalink to “Sources and Timeliness”">​</a></h2><ul><li><a href="https://xxgk.scut.edu.cn/2021/0815/c71a3558/page.htm" target="_blank" rel="noreferrer">SCUT Full-Time Undergraduate Academic Management Regulations (2021 Revision)</a>, Articles 29, 30, and 39: deferred exam conditions, pre-exam written application, dual-college approval, next-semester retake, grade recording, and GPA calculation.</li><li><a href="/assets/pdf/scut_undergraduate_handbook_2024.pdf#page=69">Undergraduate Handbook</a>, PDF pp. 69–70 (handbook pp. 67–68): same regulations and grade recording provisions.</li><li><a href="https://www2.scut.edu.cn/marine/2026/0116/c39453a617522/page.htm" target="_blank" rel="noreferrer">Retake Enrollment Notice for 2025–2026 Academic Year, Second Semester</a>: one-week enrollment window, academic system path, only retake option if missed, and arrangement publication channels for public and major-specific courses.</li><li><a href="https://www2.scut.edu.cn/ep/2018/1102/c19008a293383/page.htm" target="_blank" rel="noreferrer">Deferred Exam Application Form Download Page</a>: older version posted on the university website, for backup only. Confirm the current version with your counselor before proceeding.</li></ul><p>Policies, forms, and office assignments may change. This page can compress information for you, but it cannot stamp forms for you. Always defer to the current semester&#39;s Undergraduate Academic Affairs Office, course-offering college, and counselor notices.</p>`,57)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};